"""Fixture models generated by real ``scripts/step`` runs, several models to a run.

Starting Python and loading the CAD libraries costs more than generating a small model, so models that take the same
options share a run, up to ``MODELS_PER_RUN`` of them: a run generates its models one after another, and the class
whose fixture they are holds a test worker until its last run ends. Each model has a folder of its own,
``<name>/<name>.py``: the sidecars a run writes at one relative path land beside each model's STEP, and every report
names the model it is about by that source path.
"""

from __future__ import annotations

import collections
import os
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from common.solid_check import TIME_SCALE_VARIABLE


SCRIPTS_ROOT = Path(__file__).resolve().parents[2]
# Three to a run keeps most of what sharing saves (eight mesh fixtures: 15% more CPU than in two runs, in 40% of the time).
MODELS_PER_RUN = 3
# Other tests share the CPU, so the kernel checks get four times their default budgets.
STRETCHED_BUDGETS = {**os.environ, TIME_SCALE_VARIABLE: "4"}


def source(name: str) -> str:
    return f"{name}/{name}.py"


def write_models(project: Path, models: dict[str, str]) -> None:
    for name, text in models.items():
        (project / name).mkdir()
        (project / source(name)).write_text(text, encoding="utf-8")


def generate(project: Path, names: list[str], *options: str) -> subprocess.CompletedProcess:
    return subprocess.run(
        [sys.executable, str(SCRIPTS_ROOT / "step"), *map(source, names), *options],
        cwd=project,
        env=STRETCHED_BUDGETS,
        capture_output=True,
        text=True,
        timeout=600 * len(names),
    )


def generate_by_options(project: Path, options: dict[str, tuple[str, ...]]) -> dict[str, subprocess.CompletedProcess]:
    """Each model's run: models with the same options share runs of up to MODELS_PER_RUN, all the runs at the same time.

    A model that fails stops its run, so the models of a failed run are run again one at a time: each then has a run of
    its own, and only the failing model's tests fail.
    """
    groups = collections.defaultdict(list)
    for name, model_options in options.items():
        groups[model_options].append(name)

    def runs(names: list[str], model_options: tuple[str, ...]) -> dict[str, subprocess.CompletedProcess]:
        run = generate(project, names, *model_options)
        if run.returncode == 0 or len(names) == 1:
            return dict.fromkeys(names, run)
        return {name: generate(project, [name], *model_options) for name in names}

    shares = [(names[start:start + MODELS_PER_RUN], model_options) for model_options, names in groups.items() for start in range(0, len(names), MODELS_PER_RUN)]
    with ThreadPoolExecutor() as pool:
        shares_run = [pool.submit(runs, names, model_options) for names, model_options in shares]
    return {name: run for share in shares_run for name, run in share.result().items()}


def lines_naming(run: subprocess.CompletedProcess) -> dict[str | None, list[str]]:
    """The run's report lines by the model each names, under None for lines that name none of the run's own models."""
    names = [Path(arg).parent.name for arg in run.args[2:] if arg.endswith(".py")]
    lines = collections.defaultdict(list)
    for line in run.stderr.splitlines():
        lines[next((name for name in names if source(name) in line), None)].append(line)
    return lines
